      throw new Error(`Invalid value for ${key}: must be a boolean`);
    }
  }
}

function slugify(input, trim) {
  let out = input.toLowerCase();
  if (trim) out = out.trim();
  out = out.replace(/[^a-z0-9]+/g, '-');
  out = out.replace(/^-+|-+$/g, '');
  return out;
