import('./server.mjs').then(async ({callTool, listTools}) => {
  const tools = await listTools();
  console.log('Tools:', JSON.stringify(tools, null, 2));

  // uppercase
  console.log('uppercase:', (await callTool('text_transform', {text:'  Hello  ', mode:'uppercase'})).content[0].text);
  // uppercase, trim=false
  console.log('uppercase no-trim:', JSON.stringify((await callTool('text_transform', {text:'  Hi  ', mode:'uppercase', trim:false})).content[0].text));
  // lowercase
  console.log('lowercase:', (await callTool('text_transform', {text:'  HELLO  ', mode:'lowercase'})).content[0].text);
  // slug edge cases
  console.log('slug leading/trailing:', (await callTool('text_transform', {text:'---Hello---', mode:'slug'})).content[0].text);
  console.log('slug multi-punct:', (await callTool('text_transform', {text:'  Hello,   World!!! ', mode:'slug'})).content[0].text);
  console.log('slug alphanum:', (await callTool('text_transform', {text:'abc123XYZ', mode:'slug'})).content[0].text);
  console.log('slug all punct:', (await callTool('text_transform', {text:'!!!@@@', mode:'slug'})).content[0].text);
  console.log('slug empty:', (await callTool('text_transform', {text:'', mode:'slug'})).content[0].text);

  // errors
  for (const [label, fn] of [
    ['unknown tool', async () => callTool('nope', {text:'x', mode:'uppercase'})],
    ['bad mode', async () => callTool('text_transform', {text:'x', mode:'reverse'})],
    ['extra arg', async () => callTool('text_transform', {text:'x', mode:'uppercase', foo:1})],
    ['missing text', async () => callTool('text_transform', {mode:'uppercase'})],
    ['wrong type text', async () => callTool('text_transform', {text:123, mode:'uppercase'})],
    ['wrong type trim', async () => callTool('text_transform', {text:'x', mode:'uppercase', trim:'yes'})],
    ['null args', async () => callTool('text_transform', null)],
  ]) {
    try { await fn(); console.log(label, 'NO ERROR (bad)'); }
    catch (e) { console.log(label, '->', e.message); }
  }
});
" 2>&1"}

